SELECT distinct
 	s.id_ativo,
    r.id_readaptacao,
    r.duracao,
    TO_CHAR(r.data_inicio, 'dd/mm/yyyy') AS data_inicio,
    TO_CHAR(r.data_fim, 'dd/mm/yyyy') AS data_fim,
    u.id_unidade,
    u.nome AS unidade,
    s.id_servidor,
    s.siape AS matricula,
    s.digito_siape AS vinculo,
    p.id_pessoa,
    p.nome AS servidor,
    ta.descricao AS tipoAfastamento,
    r.justificativa,
    r.id_arquivo
FROM
    pessoas.readaptacao r
    JOIN rh.servidor s ON s.id_servidor = r.id_servidor
    JOIN comum.pessoa p ON p.id_pessoa = s.id_pessoa
    JOIN comum.unidade u ON u.id_unidade = r.id_unidade
    JOIN rh.afastamento a ON a.id_afastamento = r.id_afastamento
    JOIN rh.tipo_afastamento ta ON ta.id_tipo_afastamento = a.id_tipo
where
    r.ativo
    and s.id_ativo = 1
    AND (u.id_unidade = 27224038
        OR EXISTS (
            SELECT
                1
            FROM
                ensino.docente_turma dt
                JOIN ensino.turma t ON (dt.id_turma = t.id_turma)
                JOIN basico.turma_serie ts ON (ts.id_turma_serie = t.id_turma_serie)
                JOIN escola.escola e ON (e.id_escola = ts.id_escola)
            WHERE
                dt.id_docente = s.id_servidor
                AND dt.ativo = TRUE
                AND e.id_unidade_escola = 27224038
        )
        OR EXISTS (
            SELECT
                1
            FROM
                pessoas.vaga_administrativa va
                INNER JOIN rh.servidor servidor ON va.id_servidor = servidor.id_servidor
                INNER JOIN comum.pessoa p3 ON servidor.id_pessoa = p3.id_pessoa
            WHERE
                va.ativo = TRUE
                AND va.id_servidor = s.id_servidor
                AND (va.id_unidade = 27224038)
               
        )
    )


    )
ORDER BY
    u.nome,
    p.nome;

       
   
   
     
   select *
   from comum.unidade u ;
   
     select s.id_ativo, a.descricao,*
   from rh.servidor s  
  join rh.ativo a on a.id_ativo  = s.id_ativo 
  and a.descricao = 'EXCLUSÃO';

 select s.digito_siape,*
   from rh.servidor s 
   where s.id_servidor in (52329883,
52331110,
52330552,
52328512,
52326108,
52327101);


select
	distinct r.id_readaptacao,
	r.duracao,
	TO_CHAR(r.data_inicio,
	'dd/mm/yyyy') as data_inicio,
	TO_CHAR(r.data_fim,
	'dd/mm/yyyy') as data_fim,
	u.id_unidade,
	u.nome as unidade,
	s.id_servidor,
	s.siape as matricula,
	s.digito_siape as vinculo,
	p.id_pessoa,
	p.nome as servidor,
